{
  "root_cause": "ArrowRight increments the date by one day without skipping disabled weekend days, causing selection of closed days.",
  "repair_strategy": "Modify adjustDate to loop forward/backward by one day until a non-disabled date (respecting minDate, maxDate, disableWeekends, and disableDayFn) is found.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "a50b66482ec18884a7200882e9b523d9192b224b40b296cdd4080530f114fa75",
      "before": "        adjustDate: function(sign, days) {

            var day = this.getDate() || new Date();
            var difference = parseInt(days)*24*60*60*1000;

            var newDay;

            if (sign === 'add') {
                newDay = new Date(day.valueOf() + difference);
            } else if (sign === 'subtract') {
                newDay = new Date(day.valueOf() - difference);
            }

            this.setDate(newDay);
        },",
      "after": "        adjustDate: function(sign, days) {
            var day = this.getDate() || new Date();
            var difference = parseInt(days) * 24 * 60 * 60 * 1000;
            var newDay;
            if (sign === 'add') {
                newDay = new Date(day.valueOf() + difference);
            } else if (sign === 'subtract') {
                newDay = new Date(day.valueOf() - difference);
            }
            var step = sign === 'add' ? 1 : -1;
            var msPerDay = 24 * 60 * 60 * 1000;
            while (true) {
                var disabled = false;
                if (this._o.minDate && newDay < this._o.minDate) disabled = true;
                else if (this._o.maxDate && newDay > this._o.maxDate) disabled = true;
                else if (this._o.disableWeekends && (newDay.getDay() === 0 || newDay.getDay() === 6)) disabled = true;
                else if (this._o.disableDayFn && this._o.disableDayFn(newDay)) disabled = true;
                if (!disabled) break;
                newDay = new Date(newDay.valueOf() + step * msPerDay);
            }
            this.setDate(newDay);
        },"
    }
  ],
  "expected_accessibility_effect": "Keyboard navigation with ArrowRight/Left/Up/Down will now skip over disabled weekend dates, ensuring users can only select valid weekdays.",
  "functional_risks": [
    "Risk of infinite loop if all dates are disabled (unlikely). Slight performance impact due to looping; adjustDate is only used for arrow key navigation, so other functionality remains unchanged."
  ],
  "verification_requirements": [
    "Test that ArrowRight from Friday 2026-11-20 yields Monday 2026-11-23; ArrowLeft from Monday yields Friday; verify that arrow keys never land on Saturday or Sunday; ensure month navigation and direct date input still work."
  ]
}

